CREATE TABLE customers (
  customer_id NUMBER PRIMARY KEY,
  name        VARCHAR2(50),
  city        VARCHAR2(30),
  phone       VARCHAR2(15)
);

CREATE TABLE customer_phones (
  customer_id NUMBER REFERENCES customers(customer_id),
  phone       VARCHAR2(15),
  is_primary  CHAR(1)
);

CREATE TABLE orders (
  order_id    NUMBER PRIMARY KEY,
  customer_id NUMBER REFERENCES customers(customer_id),
  amount      NUMBER(10,2),
  status      VARCHAR2(10)
);

